      %{}
      |> ArchAstro.SDK.Codec.put_optional("token", input.token)

    ArchAstro.SDK.HTTP.request(client, :post, path,
      body: body,
      decode: {:ref, ArchAstro.SDK.Types.AuthTokens}
    )
  end
end
